//! Bible resolver — `BI`, `OT` and `NT`.
//!
//! The 66 books of the Protestant canon in English verse numbering, read from
//! `bible/{BOOK}/{chapter}.json`, generated by `scripts/build-bible.py` from
//! eBible.org's public-domain exports: the Smith & Van Dyck Arabic as `ar`,
//! the King James Version as `en`, and the World English Bible as `en_web`.
//!
//! Each verse also carries its **original language**. Old Testament verses
//! have `he`, the Hebrew Masoretic text with its Aramaic passages (Daniel,
//! Ezra). It is placed on the English verses through JPS's Hebrew verse
//! numbers, so English Genesis 31:55 carries Hebrew 32:1. New Testament
//! verses have `grc`, the Greek Textus Receptus the KJV was translated from.
//!
//! Search matches `ar` and `en`; the WEB and the originals are returned, not
//! searched.
//!
//! # Addressing
//!
//! A Bible verse needs a book as well as a chapter and verse, so these are the
//! sources that take a path:
//!
//! ```text
//! OT:GEN:1:1        Genesis 1:1               NT:JHN:3:16     John 3:16
//! BI:OT:GEN:1:1     the same, through BI      BI:GEN:1:1      testament omitted
//! OT:GEN            all of Genesis            BI:OT           the Old Testament
//! OT:GEN::5         Genesis's 5th verse       OT::100         the OT's 100th
//! ```
//!
//! A book is named by its USFM code (`GEN`, `1SA`, `JHN`), eBible's variant
//! (`JOH`), or its English name (`GENESIS`, `1SAMUEL`); the Torah's books also
//! by their Hebrew names (`BERESHIT`). The parser knows none of them — this
//! module owns the list.
//!
//! The three codes are views of one Bible. `OT` holds books 1–39 and `NT` the
//! rest; `BI` holds all 66 and takes an optional testament before the book.
//! `OT::N` is the Bible's `N`-th verse, `NT::N` the New Testament's, and the
//! ranked-search indexes are the Bible's own, which the two testaments see as
//! windows (see [`IndexKeys::Flat`]).
//!
//! # The Jewish Torah
//!
//! `TO` is the same resolver over a second edition, `torah/`: the five books
//! of Moses in Hebrew numbering, generated by `scripts/build-torah.py`. Its
//! `en` is JPS 1917, the Hebrew rides along as `he`, and `bible_ref` names the
//! same verse in `OT` — the two numberings disagree in ten places, so
//! `TO:GEN:32:1` is `OT:GEN:31:55`. The Jewish Psalms are `PS`; see
//! [`super::Psalms`].

use crate::ast::{Range, Reference, Segment};
use crate::error::Error;
use crate::record::Record;
use crate::repo::Repository;
use crate::sources::{IndexKeys, Source};
use serde::Deserialize;
use std::sync::Arc;

/// Books in the Old Testament; the rest are the New.
pub(crate) const OLD_TESTAMENT: usize = 39;

/// Books in the Torah: Genesis to Deuteronomy.
const TORAH: usize = 5;

/// Which edition a source reads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Edition {
    /// The Christian Bible in English numbering — Van Dyck, KJV and WEB, under
    /// `bible/`. `BI`, `OT` and `NT`.
    Christian,
    /// The Jewish Torah in Hebrew numbering — the Hebrew, JPS 1917, and the
    /// translations re-cut to fit, under `torah/`. `TO`.
    Jewish,
}

impl Edition {
    fn dir(self) -> &'static str {
        match self {
            Edition::Christian => "bible",
            Edition::Jewish => "torah",
        }
    }

    /// How many books its catalog holds, from Genesis on.
    fn books(self) -> usize {
        match self {
            Edition::Christian => BOOKS.len(),
            Edition::Jewish => TORAH,
        }
    }

    /// The source whose ranked-search index this edition is in.
    fn index(self) -> &'static str {
        match self {
            Edition::Christian => "BI",
            Edition::Jewish => "TO",
        }
    }
}

/// One book of the canon: its code, its English name, and every other name a
/// query may use for it. Names are written uppercase, as the parser
/// normalizes them.
pub(crate) struct Book {
    pub(crate) code: &'static str,
    pub(crate) name: &'static str,
    pub(crate) aliases: &'static [&'static str],
}

const fn book(code: &'static str, name: &'static str, aliases: &'static [&'static str]) -> Book {
    Book {
        code,
        name,
        aliases,
    }
}

